import * as React from "react"
import { Link, PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";

const userData: UserProfile = data;

const NotFoundPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="fill-Tofu"
      footerLogoFill="fill-Tofu"
      bgImage={images.bgIndex.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
      <section className="text-Tofu w-full mt-20">

      <h1 className="text-8xl text-center text-DarkSea">{t("error404.title")}</h1>
      <h2 className="text-6xl text-center">{t("error404.subtitle")}</h2>
      <h3 className="text-4xl text-center mt-4">{userData.name}</h3>
      <p className="text-center text-3xl mt-4">
        <div className="w-full max-w-2xl mx-auto my-12 text-Oatmeal">
          {t("error404.text")}
        </div>
        <Link className="mx-auto text-5xl hover:underline hover:text-Oatmeal" to="/">{t("error404.cta")}</Link>
      </p>  
        </section>
    </Layout>
  )
}

export default NotFoundPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
import SEO from "../components/seo";
import type { HeadProps } from "gatsby";
import translations from "../locales/en/index.json";
export const Head = ({ location, pageContext }: HeadProps<Record<string, unknown>, { language?: string; i18n?: { originalPath?: string } }>) => (
  <SEO
    data={userData}
    title={translations.seo["404"].title}
    description={translations.seo["404"].description}
    language={pageContext.language ?? "en"}
    languages={["en"]}
    defaultLanguage="en"
    originalPath={pageContext.i18n?.originalPath ?? location.pathname}
    noindex
  />
);
